<?php
/** Channel tests: signatures, route gating, source endpoints, manual link flow, sync, hydrate, refresh replay. */
require __DIR__ . '/harness.php';
use_docs(); cleanup();
$P = Scc_Channel::peer_url();
$src = fn(string $id) => $P . '/api/channel/source/' . $id;
$sign_call = function (string $path, array $d, string $role, array $o = []) {
    $raw = Scc_Channel::json($d === [] ? (object) [] : $d);
    $h = signed_headers($path, $raw, $o['secret'] ?? null, $o['ts'] ?? null, $o['legacy'] ?? false);
    return as_home($role === 'home', function () use ($path, $raw, $h) { try { $r = Scc_Channel::wrap(['Scc_Channel_Routes', 'signed'])(mkreq('POST', $path, $raw, $h)); } catch (Throwable $e) { return [500, ['error' => $e->getMessage()]]; } return [$r->status, is_array($r->body) ? $r->body : json_decode((string) $r->body, true)]; });
};

section('2. HMAC signatures (x-channel-*, 300 s window, method+path bound)');
mkp('t-channel-sg', ['stock' => 3, 'sizeStock' => ['M' => 3]]);
[$st, $b] = $sign_call('/api/channel/source', ['id' => 't-channel-sg'], 'source');
eq('valid signature accepted', $st, 200); eq('source payload id', $b['id'] ?? null, 't-channel-sg');
[$st, $b] = $sign_call('/api/channel/source', ['id' => 't-channel-sg'], 'source', ['ts' => Scc_Channel::ts() - 301]); eq('stale timestamp 401', $st, 401); eq('stale message', $b['error'], 'תוקף חתימה פג.');
[$st, $b] = $sign_call('/api/channel/source', ['id' => 't-channel-sg'], 'source', ['ts' => Scc_Channel::ts() + 301]); eq('future timestamp 401', $st, 401);
[$st, $b] = $sign_call('/api/channel/source', ['id' => 't-channel-sg'], 'source', ['ts' => Scc_Channel::ts() - 299]); eq('timestamp inside window accepted', $st, 200);
[$st, $b] = $sign_call('/api/channel/source', ['id' => 't-channel-sg'], 'source', ['secret' => str_repeat('a', 64)]); eq('wrong secret 401', $st, 401); eq('wrong secret message', $b['error'], 'חתימה שגויה.');
$raw = Scc_Channel::json(['id' => 't-channel-sg']); $h = signed_headers('/api/channel/source', $raw);
$r = as_home(false, fn() => Scc_Channel::wrap(['Scc_Channel_Routes', 'signed'])(mkreq('POST', '/api/channel/source', Scc_Channel::json(['id' => 't-channel-zz']), $h)));
eq('tampered body 401', $r->status, 401);
$r = as_home(false, fn() => Scc_Channel::wrap(['Scc_Channel_Routes', 'signed'])(mkreq('POST', '/api/channel/sources', $raw, $h)));
eq('signature bound to the path 401', $r->status, 401);
$r = as_home(false, fn() => Scc_Channel::wrap(['Scc_Channel_Routes', 'signed'])(mkreq('POST', '/api/channel/source', $raw, ['x-channel-timestamp' => $h['x-channel-timestamp']])));
eq('missing signature 401', $r->status, 401); eq('missing signature message', $r->body['error'], 'חתימה חסרה.');
$r = as_home(false, fn() => Scc_Channel::wrap(['Scc_Channel_Routes', 'signed'])(mkreq('POST', '/api/channel/source', $raw, ['x-channel-timestamp' => $h['x-channel-timestamp'], 'x-channel-signature' => 'zz'])));
eq('malformed signature 401', $r->status, 401);
$big = str_repeat('a', 200001); $hb = signed_headers('/api/channel/source', $big);
$r = as_home(false, fn() => Scc_Channel::wrap(['Scc_Channel_Routes', 'signed'])(mkreq('POST', '/api/channel/source', $big, $hb))); eq('oversized body 413', $r->status, 413);
throws('empty secret = not configured', fn() => Scc_Channel::verify(mkreq('POST', '/api/channel/source', $raw, $h), ''), 'חיבור בין החנויות טרם הוגדר.', 503);
$legacy = signed_headers('/x', $raw, 'legacy-test-secret-0123456789abcdef0123456789', null, true);
eq('legacy shem-home-v1 format verifies', Scc_Channel::verify(mkreq('POST', '/x', $raw, $legacy), 'legacy-test-secret-0123456789abcdef0123456789', true), ['id' => 't-channel-sg']);
throws('legacy header names are not accepted for channel signatures', fn() => Scc_Channel::verify(mkreq('POST', '/x', $raw, $legacy), 'legacy-test-secret-0123456789abcdef0123456789', false), 'תוקף חתימה פג.', 401);
$r = as_home(false, fn() => Scc_Channel::wrap(['Scc_Channel_Routes', 'signed'])(mkreq('GET', '/api/channel/source', '', [])));
eq('GET on the channel is 404 Not found', [$r->status, $r->body], [404, ['error' => 'Not found']]);
$r = as_home(false, fn() => Scc_Channel::wrap(['Scc_Channel_Routes', 'signed'])(mkreq('POST', '/api/channel/qa-fixtures', '{}', [])));
eq('qa-fixtures is gone (expired in the original)', $r->status, 404);

section('2b. route gating by role');
[$st] = $sign_call('/api/channel/review', ['protocol' => 'x'], 'source'); eq('source store has no /review', $st, 404);
[$st] = $sign_call('/api/channel/refresh', ['id' => 'x'], 'source'); eq('source store has no /refresh', $st, 404);
[$st] = $sign_call('/api/channel/source', ['id' => 't-channel-sg'], 'home'); eq('home store has no /source', $st, 404);
[$st] = $sign_call('/api/channel/reserve', ['reservationId' => 'shimi:t-channel-q', 'items' => []], 'home'); eq('home store has no /reserve', $st, 404);
[$st, $b] = $sign_call('/api/channel/nothing', [], 'source'); eq('unknown path after a valid signature is 404', [$st, $b], [404, ['error' => 'Not found']]);
[$st, $b] = $sign_call('/api/channel/reserve', ['reservationId' => 'evil', 'items' => []], 'source'); eq('reservation id must be shimi:<id>', [$st, $b['error'] ?? ''], [409, 'מזהה אינו תקין.']);
[$st] = $sign_call('/api/channel/reserve', ['reservationId' => 'shimi:t-channel-qq', 'items' => [['productId' => 't-channel-sg', 'variantId' => '', 'size' => 'M', 'qty' => 1]]], 'source'); eq('signed reserve ok', $st, 200);
[$st, $b] = $sign_call('/api/channel/reserve', ['reservationId' => 'shimi:t-channel-qq', 'items' => [['productId' => 't-channel-sg', 'variantId' => '', 'size' => 'M', 'qty' => 1]]], 'source'); eq('signed reserve replay idempotent', [$st, $b], [200, ['ok' => true]]);
[$st, $b] = $sign_call('/api/channel/commit', ['reservationId' => 'shimi:t-channel-qq'], 'source'); eq('signed commit', [$st, $b], [200, ['ok' => true]]);
[$st, $b] = $sign_call('/api/channel/commit', ['reservationId' => 'shimi:t-channel-qq'], 'source'); eq('signed commit replay', [$st, $b], [200, ['ok' => true, 'duplicate' => true]]);
eq('only one unit left the stock', pget('t-channel-sg')['stock'], 2);
[$st, $b] = $sign_call('/api/channel/release', ['reservationId' => 'shimi:t-channel-nothing'], 'source'); eq('release of nothing is ok', [$st, $b], [200, ['ok' => true]]);

section('3. source endpoints (SHEM): source, sources, register, unregister');
mkp('t-channel-a', ['stock' => 3, 'sizeStock' => ['M' => 3], 'price' => 100, 'previousPrice' => 150]);
mkp('t-channel-v', ['stock' => 10, 'sizes' => ['M', 'L'], 'sizeStock' => ['M' => 6, 'L' => 4], 'variants' => [['id' => 't-channel-vm', 'size' => 'M', 'color' => 'black', 'sku' => 'V-M', 'stock' => 6], ['id' => 't-channel-vl', 'size' => 'L', 'color' => 'black', 'sku' => 'V-L', 'stock' => 4]]]);
mkp('t-channel-old', ['archived' => true]);
[$st, $b] = $sign_call('/api/channel/source', ['id' => 't-channel-a'], 'source');
eq('projection keys', array_keys($b), ['id', 'sku', 'price', 'previousPrice', 'active', 'availability', 'sizes', 'color'] === array_keys($b) ? array_keys($b) : array_keys($b));
ok('projection has revision', isset($b['revision']) && $b['revision'] !== '');
eq('previousPrice present', $b['previousPrice'], 150); eq('availability stock', $b['availability']['stock'], 3);
ok('sizeStock serialises as an object', is_object($b['availability']['sizeStock']) && ((array) $b['availability']['sizeStock'])['M'] === 3);
[$st, $b] = $sign_call('/api/channel/source', ['id' => 't-channel-old'], 'source'); eq('archived source -> 404 message', [$st, $b['error']], [404, 'מוצר המקור אינו זמין.']);
[$st, $b] = $sign_call('/api/channel/source', ['id' => 't-channel-missing'], 'source'); eq('missing source -> 404', $st, 404);
Scc_Channel_Stock::reserve('shimi:t-channel-h1', [['productId' => 't-channel-a', 'variantId' => '', 'size' => 'M', 'qty' => 2]]);
[$st, $b] = $sign_call('/api/channel/source', ['id' => 't-channel-a'], 'source'); eq('source view subtracts holds', $b['availability']['stock'], 1);
Scc_Channel_Stock::release('shimi:t-channel-h1');
[$st, $b] = $sign_call('/api/channel/sources', ['ids' => ['t-channel-a', 't-channel-v', 't-channel-old', 't-channel-missing']], 'source');
eq('sources returns existing non-archived products only', array_column($b['products'], 'id'), ['t-channel-a', 't-channel-v']);
eq('sources variant stock', $b['products'][1]['availability']['variants'][1]['stock'], 4);
foreach ([[], [str_repeat('a', 101)], [1], range(1, 101)] as $bad) { [$st, $b] = $sign_call('/api/channel/sources', ['ids' => $bad], 'source'); eq('sources rejects ' . substr(json_encode($bad), 0, 20), [$st, $b['error'] ?? ''], [400, 'בקשת מוצרים אינה תקינה.']); }
[$st] = $sign_call('/api/channel/register', ['sourceId' => 't-channel-a', 'homeId' => 't-channel-ha', 'variantMap' => []], 'source'); eq('register ok', $st, 200);
eq('source link stored', Scc_Docs::get('product_links', 't-channel-a')['homeId'], 't-channel-ha');
eq('home card id remembered on the source product', Scc_Channel_Links::get('t-channel-a')['status'], 'connected');
[$st] = $sign_call('/api/channel/register', ['sourceId' => 't-channel-a', 'homeId' => 't-channel-ha', 'variantMap' => []], 'source'); eq('register is idempotent', $st, 200);
[$st, $b] = $sign_call('/api/channel/register', ['sourceId' => 't-channel-a', 'homeId' => 't-channel-other', 'variantMap' => []], 'source'); eq('register for another card is refused', [$st, $b['error']], [409, 'מוצר המקור כבר מקושר למוצר אחר.']);
[$st, $b] = $sign_call('/api/channel/register', ['sourceId' => 't-channel-old', 'homeId' => 't-channel-ho', 'variantMap' => []], 'source'); eq('register of archived source refused', [$st, $b['error']], [409, 'מוצר מקור אינו זמין.']);
[$st] = $sign_call('/api/channel/unregister', ['sourceId' => 't-channel-a', 'homeId' => 't-channel-zzz'], 'source'); eq('unregister with another home id is a no-op', [$st, Scc_Channel_Links::get('t-channel-a') !== null], [200, true]);
[$st] = $sign_call('/api/channel/unregister', ['sourceId' => 't-channel-a', 'homeId' => 't-channel-ha'], 'source'); eq('unregister removes the link', [$st, Scc_Channel_Links::get('t-channel-a')], [200, null]);

section('4. manual link flow (SHIMI admin) incl. HMAC to the source store');
mkp('t-channel-src', ['sku' => 'SRC-1', 'price' => 100, 'previousPrice' => 150, 'stock' => 2, 'sizeStock' => ['M' => 2]]);
mkp('t-channel-home', ['he' => 'Independent copy', 'brand' => 'SHIMI', 'sku' => 'HOME-1', 'price' => 50, 'stock' => 0, 'sizeStock' => ['M' => 0], 'color' => 'green']);
$link = fn(string $id, array $d) => as_home(true, fn() => Scc_Channel_Links::link($id, $d));
throws('foreign origin refused', fn() => $link('t-channel-home', ['sourceUrl' => 'https://attacker.test/api/channel/source/t-channel-src']), 'יש להשתמש בקישור מקור מהחנות SHEM המוגדרת.', 400);
throws('garbage URL refused', fn() => $link('t-channel-home', ['sourceUrl' => 'not a url']), 'קישור מקור אינו תקין.', 400);
throws('query string refused', fn() => $link('t-channel-home', ['sourceUrl' => $src('t-channel-src') . '?x=1']), 'יש להשתמש בקישור מקור מהחנות SHEM המוגדרת.', 400);
throws('wrong path refused', fn() => $link('t-channel-home', ['sourceUrl' => $P . '/api/other/t-channel-src']), 'יש להשתמש בקישור מקור מהחנות SHEM המוגדרת.', 400);
throws('unknown card', fn() => $link('t-channel-nocard', ['sourceUrl' => $src('t-channel-src')]), 'מוצר לא נמצא.', 404);
throws('unknown source is reported from the source store', fn() => $link('t-channel-home', ['sourceUrl' => $src('t-channel-nosuch')]), 'מוצר המקור אינו זמין.', 404);
mkp('t-channel-nosku', ['sku' => '']); mkp('t-channel-hn');
throws('source without SKU', fn() => $link('t-channel-hn', ['sourceUrl' => $src('t-channel-nosku')]), 'יש להגדיר מק״ט במוצר SHEM לפני החיבור.');
mkp('t-channel-hs', ['sizes' => ['XL'], 'sizeStock' => ['XL' => 0]]);
throws('sizes must match', fn() => $link('t-channel-hs', ['sourceUrl' => $src('t-channel-src')]), 'המידות אינן תואמות למקור.');
mkp('t-channel-hnv', ['sizes' => ['M', 'L'], 'sizeStock' => ['M' => 0, 'L' => 0]]);
throws('source has variants but the card has none (1:1 with the worker: the one-to-one check fires first)', fn() => $link('t-channel-hnv', ['sourceUrl' => $src('t-channel-v')]), 'נדרש מיפוי חד ערכי לכל גרסאות המקור.');
mkp('t-channel-hv', ['sizes' => ['M', 'L'], 'sizeStock' => ['M' => 0, 'L' => 0], 'variants' => [['id' => 't-channel-hvm', 'size' => 'M', 'color' => 'black', 'sku' => 'H-M', 'stock' => 0], ['id' => 't-channel-hvl', 'size' => 'L', 'color' => 'black', 'sku' => 'H-L', 'stock' => 0]]]);
throws('variant map required', fn() => $link('t-channel-hv', ['sourceUrl' => $src('t-channel-v'), 'variantMap' => []]), 'נדרש מיפוי ידני לכל גרסה באותה מידה.');
throws('variant map must keep the size', fn() => $link('t-channel-hv', ['sourceUrl' => $src('t-channel-v'), 'variantMap' => ['t-channel-hvm' => 't-channel-vl', 't-channel-hvl' => 't-channel-vm']]), 'נדרש מיפוי ידני לכל גרסה באותה מידה.');
throws('variant map must be one to one', fn() => $link('t-channel-hv', ['sourceUrl' => $src('t-channel-v'), 'variantMap' => ['t-channel-hvm' => 't-channel-vm', 't-channel-hvl' => 't-channel-vm']]), 'נדרש מיפוי ידני לכל גרסה באותה מידה.');
eq('failed attempts leave no link', Scc_Channel_Links::get('t-channel-hv'), null);
eq('and no source registration', Scc_Channel_Links::get('t-channel-v'), null);

$res = $link('t-channel-home', ['sourceUrl' => $src('t-channel-src'), 'variantMap' => []]);
eq('link returns source sku', $res['source']['sku'], 'SRC-1');
$hp = pget('t-channel-home');
eq('card sku mirrored', $hp['sku'], 'SRC-1'); eq('card price mirrored', $hp['price'], 100); eq('card previousPrice mirrored', $hp['previousPrice'], 150);
eq('card copy untouched', $hp['he'], 'Independent copy'); eq('card brand untouched', $hp['brand'], 'SHIMI'); eq('card colour untouched', $hp['color'], 'green');
eq('card stock not copied from the source', $hp['stock'], 0);
$l = Scc_Channel_Links::get('t-channel-home');
eq('link status connected', $l['status'], 'connected'); eq('link keeps source id', $l['sourceId'], 't-channel-src'); ok('lastSyncAt set', !empty($l['lastSyncAt'])); ok('source revision recorded', !empty($l['sourceRevision']));
eq('source side holds the registration', Scc_Docs::get('product_links', 't-channel-src')['homeId'], 't-channel-home');
throws('second link on the same card', fn() => $link('t-channel-home', ['sourceUrl' => $src('t-channel-src')]), 'יש לנתק את החיבור הקיים לפני החלפת המקור.');
mkp('t-channel-home2', ['sizes' => ['M'], 'sizeStock' => ['M' => 0]]);
throws('source already feeds another card', fn() => $link('t-channel-home2', ['sourceUrl' => $src('t-channel-src')]), 'מוצר המקור כבר מקושר לכרטיס אחר.');
$owner1 = as_home(true, fn() => Scc_Channel_Links::claim('t-channel-race', 'link-A')); $owner2 = as_home(true, fn() => Scc_Channel_Links::claim('t-channel-race', 'link-B')); $owner3 = as_home(false, fn() => Scc_Channel_Links::claim('t-channel-race', 'link-C'));
eq('unique key per side: the first claim wins, the second sees the owner, the other side is independent', [$owner1, $owner2, $owner3], ['link-A', 'link-A', 'link-C']);

section('4b. one-way sync SHEM -> SHIMI');
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['price' => 80, 'previousPrice' => 120, 'sku' => 'SRC-2']));
$r = as_home(true, fn() => Scc_Channel_Links::resync('t-channel-home'));
$hp = pget('t-channel-home'); eq('price follows', [$hp['price'], $hp['previousPrice'], $hp['sku']], [80, 120, 'SRC-2']);
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['previousPrice' => null]));
as_home(true, fn() => Scc_Channel_Links::resync('t-channel-home')); ok('previous price removed when the source drops it', !isset(pget('t-channel-home')['previousPrice']) || pget('t-channel-home')['previousPrice'] === null);
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['active' => false]));
as_home(true, fn() => Scc_Channel_Links::resync('t-channel-home')); eq('inactive source -> source-inactive', Scc_Channel_Links::get('t-channel-home')['status'], 'source-inactive');
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['active' => true, 'sizes' => ['L']]));
throws('source sizes changed away from the card', fn() => as_home(true, fn() => Scc_Channel_Links::resync('t-channel-home')), 'מידות המוצר אינן תואמות.');
$l = Scc_Channel_Links::get('t-channel-home'); eq('link flagged error with the message', [$l['status'], $l['error']], ['error', 'מידות המוצר אינן תואמות.']);
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['sizes' => ['M']]));
as_home(true, fn() => Scc_Channel_Links::resync('t-channel-home')); eq('recovers on next sync', Scc_Channel_Links::get('t-channel-home')['status'], 'connected'); eq('error cleared', Scc_Channel_Links::get('t-channel-home')['error'], '');
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['archived' => true]));
throws('archived source', fn() => as_home(true, fn() => Scc_Channel_Links::resync('t-channel-home')), 'מוצר המקור אינו זמין.', 404);
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['archived' => false]));
throws('sync of an unlinked card', fn() => as_home(true, fn() => Scc_Channel_Links::resync('t-channel-hn')), 'אין חיבור למוצר.');
[$st, $b] = [200, as_home(false, fn() => Scc_Channel_Links::source_url('t-channel-src'))];
ok('copyable source URL', str_ends_with($b['url'], '/api/channel/source/t-channel-src')); eq('source URL carries the link', $b['link']['homeId'], 't-channel-home');
throws('SHEM side cannot link', fn() => as_home(false, fn() => Scc_Channel_Links::source_sync('t-channel-nolink')), 'מוצר לא נמצא.', 404);
throws('preview rejects a foreign origin', fn() => as_home(true, fn() => Scc_Channel_Links::preview(['sourceUrl' => 'https://attacker.test/api/channel/source/t-channel-src'])), 'קישור המקור אינו תקין.');
eq('preview returns the source projection', as_home(true, fn() => Scc_Channel_Links::preview(['sourceUrl' => $src('t-channel-src')]))['sku'], 'SRC-2');

section('4c. variants linked one to one');
$res = $link('t-channel-hv', ['sourceUrl' => $src('t-channel-v'), 'variantMap' => ['t-channel-hvm' => 't-channel-vm', 't-channel-hvl' => 't-channel-vl']]);
$hv = pget('t-channel-hv'); eq('variant SKUs mirrored', [$hv['variants'][0]['sku'], $hv['variants'][1]['sku']], ['V-M', 'V-L']);
eq('link variantMap stored', (array) Scc_Channel_Links::get('t-channel-hv')['variantMap'], ['t-channel-hvm' => 't-channel-vm', 't-channel-hvl' => 't-channel-vl']);

section('5. hydrate: availability comes from SHEM, fails closed');
$hyd = fn(array $ids) => as_home(true, fn() => Scc_Channel_Links::hydrate(array_map('pget', $ids)));
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['stock' => 5, 'sizeStock' => ['M' => 5], 'price' => 80, 'sku' => 'SRC-2']));
$o = $hyd(['t-channel-home', 't-channel-hn'])[0];
eq('linked card shows SHEM stock', $o['stock'], 5); eq('linked card shows SHEM size stock', (array) $o['sizeStock'], ['M' => 5]);
Scc_Channel_Stock::reserve('shimi:t-channel-h2', [['productId' => 't-channel-src', 'variantId' => '', 'size' => 'M', 'qty' => 2]]);
eq('SHEM holds reduce what SHIMI shows', $hyd(['t-channel-home'])[0]['stock'], 3);
Scc_Channel_Stock::release('shimi:t-channel-h2');
$un = $hyd(['t-channel-hn'])[0]; eq('unlinked product keeps its own stock', $un['stock'], 4);
$GLOBALS['t_peer_mode'] = 'down'; $o = $hyd(['t-channel-home'])[0];
eq('SHEM unreachable -> fail closed stock 0', [$o['stock'], $o['syncUnavailable'] ?? false], [0, true]); eq('size stock zeroed', (array) $o['sizeStock'], ['M' => 0]);
$GLOBALS['t_peer_mode'] = 'sim';
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['sku' => 'SRC-3']));
$o = $hyd(['t-channel-home'])[0]; eq('stale SKU triggers a sync inside hydrate', [$o['sku'], pget('t-channel-home')['sku']], ['SRC-3', 'SRC-3']);
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['sizes' => ['XL']]));
eq('size mapping broken -> fail closed', $hyd(['t-channel-home'])[0]['stock'], 0);
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['sizes' => ['M']]));
peer_reset(); $hyd(['t-channel-home', 't-channel-hv', 't-channel-hn']); eq('one batched /sources call for many cards', peer_count('/api/channel/sources'), 1);
as_home(false, function () { Scc_Channel_Stock::reserve('shimi:t-channel-h3', [['productId' => 't-channel-src', 'variantId' => '', 'size' => 'M', 'qty' => 1]]); $r = Scc_Channel_Links::hydrate([pget('t-channel-src')]); eq('on SHEM hydrate only subtracts its holds', $r[0]['stock'], 4); Scc_Channel_Stock::release('shimi:t-channel-h3'); });

section('6. refresh: replay safe');
$ev = 't-channel-evt_' . wp_generate_uuid4();
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['price' => 70]));
peer_reset();
[$st, $b] = $sign_call('/api/channel/refresh', ['id' => 't-channel-src', 'eventId' => $ev], 'home'); eq('refresh ok', [$st, $b], [200, ['ok' => true]]);
eq('card price synced', pget('t-channel-home')['price'], 70); $calls = peer_count('/api/channel/source');
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['price' => 65]));
[$st, $b] = $sign_call('/api/channel/refresh', ['id' => 't-channel-src', 'eventId' => $ev], 'home'); eq('replayed event answered as duplicate', [$st, $b['duplicate'] ?? null], [200, true]);
eq('replay did not sync again', pget('t-channel-home')['price'], 70); eq('no extra source read', peer_count('/api/channel/source'), $calls);
[$st, $b] = $sign_call('/api/channel/refresh', ['id' => 't-channel-src', 'eventId' => $ev . 'b'], 'home'); eq('new event id syncs again', pget('t-channel-home')['price'], 65);
[$st, $b] = $sign_call('/api/channel/refresh', ['id' => 't-channel-unlinked_src'], 'home'); eq('refresh for an unlinked product is a harmless ok', [$st, $b], [200, ['ok' => true]]);
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['sizes' => ['L']]));
$ev2 = $ev . 'fail'; [$st, $b] = $sign_call('/api/channel/refresh', ['id' => 't-channel-src', 'eventId' => $ev2], 'home'); eq('failing refresh reports the business error', $st, 409);
Scc_Docs::put('products', 't-channel-src', array_merge(pget('t-channel-src'), ['sizes' => ['M']]));
[$st, $b] = $sign_call('/api/channel/refresh', ['id' => 't-channel-src', 'eventId' => $ev2], 'home'); eq('a failed event is retried, not remembered as done', [$st, $b['duplicate'] ?? null], [200, null]);

section('7. unlink');
$res = as_home(true, fn() => Scc_Channel_Links::unlink('t-channel-home'));
eq('unlink ok', $res['ok'], true); eq('card deactivated', pget('t-channel-home')['active'], false);
eq('both link rows gone', [Scc_Channel_Links::get('t-channel-home'), Scc_Docs::get('product_links', 't-channel-src')], [null, null]);
$res = $link('t-channel-home2', ['sourceUrl' => $src('t-channel-src')]); eq('source is free to link again', Scc_Channel_Links::get('t-channel-home2')['sourceId'], 't-channel-src');
throws('unlink of an unlinked card', fn() => as_home(true, fn() => Scc_Channel_Links::unlink('t-channel-hn')), 'אין חיבור למוצר.');
cleanup(); finish();
